    function testFuzz_property(address caller, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length == vs.length);
        vm.assume(tos.length > 0);
        for (uint i = 0; i < vs.length; i++) {
            vs[i] = bound(vs[i], 0, type(uint256).max / 1000000000000000000);
        }
        vm.prank(caller);
        bool ok;
        try c.transfer(tos, vs) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        assertTrue(!ok || caller == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    }
}
